CREATE TABLE IF NOT EXISTS societies(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(150) NOT NULL,address VARCHAR(255) NOT NULL,status ENUM('PENDING','VERIFIED') DEFAULT 'PENDING');
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('RESIDENT','COOK','SOCIETY_MANAGER','ADMIN') NOT NULL,society_id INT,flat VARCHAR(30),FOREIGN KEY(society_id) REFERENCES societies(id));
CREATE TABLE IF NOT EXISTS cooks(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT UNIQUE NOT NULL, cuisine VARCHAR(150) NOT NULL,bio TEXT,price INT NOT NULL,experience INT DEFAULT 0,verified BOOLEAN DEFAULT FALSE,available_from TIME DEFAULT '06:00:00',available_to TIME DEFAULT '21:00:00',FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS bookings(id INT AUTO_INCREMENT PRIMARY KEY,resident_id INT NOT NULL,cook_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,start_time TIME NOT NULL,end_time TIME NOT NULL,amount INT NOT NULL,status ENUM('PENDING','ACTIVE','CANCELLED','EXPIRED') DEFAULT 'PENDING',expires_at DATETIME NOT NULL,FOREIGN KEY(resident_id) REFERENCES users(id),FOREIGN KEY(cook_id) REFERENCES cooks(id),INDEX(cook_id,status));
CREATE TABLE IF NOT EXISTS payments(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,amount INT NOT NULL,order_id VARCHAR(100) UNIQUE,payment_id VARCHAR(100) UNIQUE,status ENUM('PENDING','SUCCESS','FAILED') DEFAULT 'PENDING',FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS sessions(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT NOT NULL,cook_id INT NOT NULL,service_date DATE NOT NULL,status ENUM('SCHEDULED','IN_PROGRESS','COMPLETED','MISSED') DEFAULT 'SCHEDULED',check_in DATETIME,check_out DATETIME,UNIQUE(booking_id,service_date),FOREIGN KEY(booking_id) REFERENCES bookings(id),FOREIGN KEY(cook_id) REFERENCES cooks(id));
CREATE TABLE IF NOT EXISTS leaves(id INT AUTO_INCREMENT PRIMARY KEY,cook_id INT NOT NULL,start_date DATE NOT NULL,end_date DATE NOT NULL,reason VARCHAR(255),status ENUM('PENDING','APPROVED','REJECTED') DEFAULT 'PENDING',FOREIGN KEY(cook_id) REFERENCES cooks(id));
CREATE TABLE IF NOT EXISTS replacements(id INT AUTO_INCREMENT PRIMARY KEY,session_id INT NOT NULL UNIQUE,reason VARCHAR(255),status ENUM('PENDING','ASSIGNED') DEFAULT 'PENDING',FOREIGN KEY(session_id) REFERENCES sessions(id));
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,booking_id INT UNIQUE NOT NULL,rating INT NOT NULL,comment VARCHAR(500),FOREIGN KEY(booking_id) REFERENCES bookings(id));
CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,message VARCHAR(500),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
